list_pages.code:
import (
	"fmt"
)

resp, err := client.Pages().ListPages(ctx, map[string]any{"search": "about", "visibility": "open", "sort": "name", "order": "asc"}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["pages"].([]any) {
	page := row.(map[string]any)
	fmt.Println(page["id"], page["name"], page["url"], page["visibility"])
}
fmt.Println(body["pagination"].(map[string]any)["has_next"])

